package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;import java.util.regex.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public class LocalisationResourcesTest {
 static Map<String,String> strings(String folder)throws Exception{Path p=Path.of("src/main/res",folder,"strings.xml");if(!Files.exists(p))p=Path.of("app/src/main/res",folder,"strings.xml");DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);NodeList nodes=f.newDocumentBuilder().parse(p.toFile()).getElementsByTagName("string");Map<String,String> out=new HashMap<>();for(int n=0;n<nodes.getLength();n++){Element e=(Element)nodes.item(n);assertNull("Duplicate resource",out.put(e.getAttribute("name"),e.getTextContent()));}return out;}
 static Set<String> formats(String value){Set<String> result=new HashSet<>();Matcher m=Pattern.compile("%[0-9]+\\$[a-z]").matcher(value);while(m.find())result.add(m.group());return result;}
 @Test public void everyHungarianResourceHasCompleteEnglishTranslation()throws Exception{Map<String,String> en=strings("values"),hu=strings("values-hu");assertEquals(hu.keySet(),en.keySet());assertTrue(en.size()>300);for(String key:hu.keySet()){assertFalse(key,en.get(key).isBlank());assertFalse(key,hu.get(key).isBlank());assertEquals(key,formats(hu.get(key)),formats(en.get(key)));}}
 @Test public void englishContainsNoHungarianUiSentences()throws Exception{for(var row:strings("values").entrySet())assertFalse(row.getKey(),Pattern.compile("[áéíóöőúüűÁÉÍÓÖŐÚÜŰ]").matcher(row.getValue().replace("Lőrincz László","")).find());}
 @Test public void actionAndLegalTranslationsAreContextCorrect()throws Exception{Map<String,String> en=strings("values"),hu=strings("values-hu");String add=hu.entrySet().stream().filter(e->e.getValue().equals("\"Hozzáadás\"")).findFirst().orElseThrow().getKey();assertEquals("\"Add\"",en.get(add));assertTrue(en.get("about_license").contains("GPL-3.0-only"));assertTrue(en.get("about_version").contains("%1$s"));}
}
